fn setup(attrs: Value) -> Harness {
    let mut h = Harness::new();
    let name = if attrs["Fifo"] == true { "q.fifo" } else { "q" };
    h.ok(json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attrs}));
    h
