fn send_batch(h: &mut Harness, q: &str, entries: Value) -> Value {
    h.run(json!({"Command": "SendMessageBatch", "QueueName": q, "Entries": entries}))
}

fn code(r: &Value) -> &str {
    assert_eq!(r["ok"], false, "{r}");
    r["error"]["code"].as_str().unwrap()
}

